-- Capture the current equipment -> condition -> identity chain; strip only our keys.
alter function bitd.validate_character_patch(jsonb) rename to validate_character_pre_human_patch;
create function bitd.validate_character_human_patch(p_patch jsonb) returns void
language plpgsql set search_path = '' as $$
declare e record; n record; item jsonb; slot jsonb;
begin
 for e in select * from jsonb_each(p_patch) where key in ('operative','radical','veteran') loop
  if jsonb_typeof(e.value)<>'object' then raise exception 'Expected % record',e.key; end if;
  for n in select * from jsonb_each(e.value) loop
   if (e.key='operative' and n.key in ('controlAction','coverIdentity','coverNotes','dropEntity','operations')) or (e.key='radical' and n.key in ('radicalizedBy','cause','supplier','praxis','dedication','operations')) or (e.key='veteran' and n.key in ('tours','damage','helps','hobby','assistance','operations')) then
    if jsonb_typeof(n.value)<>'string' or length(n.value #>> '{}')>12000 then raise exception 'Invalid specialized text'; end if;
    if n.key='controlAction' and (n.value #>> '{}')<>'' and not (n.value #>> '{}')=any(array['hunt','study','survey','tinker','finesse','prowl','skirmish','wreck','attune','command','consort','sway']) then raise exception 'Choose an action for Control'; end if;
   elsif e.key='operative' and n.key='dropLoad' then
    if not bitd.character_record_integer(n.value,2) then raise exception 'Dead Drop is limited to two load'; end if;
   elsif e.key='operative' and n.key in ('dropAssetUsed','sleeperUsed') then
    if jsonb_typeof(n.value)<>'boolean' then raise exception 'Invalid operation use'; end if;
   elsif e.key='operative' and n.key='backingFactions' then
    if jsonb_typeof(n.value)<>'array' or jsonb_array_length(n.value)>2 then raise exception 'Operative has at most two backing factions'; end if;
    for item in select * from jsonb_array_elements(n.value) loop
     if jsonb_typeof(item)<>'object' or not item ?& array['name','tier','mission','failure','prestige','help','notes'] or (item-array['name','tier','mission','failure','prestige','help','notes'])<>'{}'::jsonb then raise exception 'Incomplete backing record'; end if;
     if not bitd.character_record_integer(item->'tier',6) or not bitd.character_record_integer(item->'failure',4) then raise exception 'Invalid backing Tier or failure clock'; end if;
     for slot in select value from jsonb_each(item-array['tier','failure']) loop
      if jsonb_typeof(slot)<>'string' or length(slot #>> '{}')>12000 then raise exception 'Invalid backing text'; end if;
     end loop;
    end loop;
   elsif e.key='radical' and n.key='bandoliers' then
    if jsonb_typeof(n.value)<>'array' or jsonb_array_length(n.value)<>2 then raise exception 'Record two bandoliers'; end if;
    for item in select * from jsonb_array_elements(n.value) loop
     if jsonb_typeof(item)<>'array' or jsonb_array_length(item)<>3 then raise exception 'Each bandolier has three slots'; end if;
     for slot in select * from jsonb_array_elements(item) loop
      if jsonb_typeof(slot)<>'string' or length(slot #>> '{}')>12000 then raise exception 'Invalid explosive record'; end if;
     end loop;
    end loop;
   elsif e.key='radical' and n.key='works' then
    if jsonb_typeof(n.value)<>'array' or jsonb_array_length(n.value)>30 then raise exception 'Expected bounded literature records'; end if;
    for item in select * from jsonb_array_elements(n.value) loop
     if jsonb_typeof(item)<>'object' or not item ?& array['name','progress','circulating','contribution','notes'] or (item-array['name','progress','circulating','contribution','notes'])<>'{}'::jsonb then raise exception 'Incomplete literature record'; end if;
     if not bitd.character_record_integer(item->'progress',4) or jsonb_typeof(item->'circulating')<>'boolean' then raise exception 'Invalid literature progress/status'; end if;
     for slot in select value from jsonb_each(item-array['progress','circulating']) loop
      if jsonb_typeof(slot)<>'string' or length(slot #>> '{}')>12000 then raise exception 'Invalid literature text'; end if;
     end loop;
    end loop;
   else raise exception 'Unknown % field: %',e.key,n.key; end if;
  end loop;
 end loop;
end $$;
create function bitd.validate_character_patch(p_patch jsonb) returns void
language plpgsql set search_path = '' as $$
begin
 perform bitd.validate_character_pre_human_patch(p_patch-array['operative','radical','veteran']);
 perform bitd.validate_character_human_patch(p_patch);
end $$;
create function bitd.check_character_human_state() returns trigger
language plpgsql set search_path = '' as $$
declare item jsonb; resource_name text; resource_ability text; active_works integer;
begin
 perform bitd.validate_character_human_patch(new.data);
 if (new.data ? 'operative' and new.data->>'playbook'<>'Operative') or (new.data ? 'radical' and new.data->>'playbook'<>'Radical') or (new.data ? 'veteran' and new.data->>'playbook'<>'Veteran') then raise exception 'Specialized record requires its saved playbook'; end if;
 if new.data->>'playbook'='Operative' then
  if jsonb_array_length(new.data->'operative'->'backingFactions')>1 and not (new.data->'abilities') ? 'Double Agent' then raise exception 'Second backing faction requires Double Agent'; end if;
  if (new.data->'operative'->>'controlAction')<>'' and not (new.data->'abilities') ? 'Control' then raise exception 'Control action requires Control'; end if;
  if ((new.data->'operative'->>'dropLoad')::integer>0 or (new.data->'operative'->>'dropAssetUsed')::boolean) and not (new.data->'abilities') ? 'Dead Drop' then raise exception 'Dead Drop use requires its ability'; end if;
  if (new.data->'operative'->>'sleeperUsed')::boolean and not (new.data->'abilities') ? 'Sleeper Agents' then raise exception 'Sleeper Agent use requires its ability'; end if;
  resource_name := 'precision'; resource_ability := 'Clean';
 elsif new.data->>'playbook'='Radical' then
  select count(*) into active_works from jsonb_array_elements(new.data->'radical'->'works') w where (w->>'circulating')::boolean;
  if active_works>4 then raise exception 'At most four works may circulate effectively'; end if;
  for item in select * from jsonb_array_elements(new.data->'radical'->'works') loop
   if (item->>'circulating')::boolean and ((item->>'progress')::integer<>4 or not (new.data->'abilities') ? 'Pamphleteer') then raise exception 'Circulating works require completed Pamphleteer projects'; end if;
  end loop;
  resource_name := 'conviction'; resource_ability := 'True Believer';
 elsif new.data->>'playbook'='Veteran' then
  if not (new.data->'abilities') ? 'Military Discipline' then raise exception 'Veteran retains starting Military Discipline'; end if;
  resource_name := 'training'; resource_ability := 'Military Discipline';
 end if;
 if resource_name is not null then
  for item in select * from jsonb_array_elements(new.data->'resources') loop
   if lower(trim(item->>'name'))=resource_name then
    if (item->>'capacity')::integer<>2 then raise exception 'Published playbook resource has two uses'; end if;
    if (item->>'used')::integer>0 and not (new.data->'abilities') ? resource_ability then raise exception 'Resource use requires %',resource_ability; end if;
   end if;
  end loop;
 end if;
 return new;
end $$;
create trigger character_human_check before insert or update on bitd.characters for each row execute function bitd.check_character_human_state();
-- Preserve ALL prior nested merges under the same authenticated row lock.
create or replace function bitd.patch_character(p_character uuid,p_patch jsonb) returns bitd.characters
language plpgsql security definer set search_path = '' as $$
declare result bitd.characters; merged jsonb; field text;
begin
 select * into result from bitd.characters where id=p_character for update;
 if not found or bitd.campaign_role(result.campaign_id) is null or (bitd.campaign_role(result.campaign_id)<>'gm' and result.owner_id is distinct from auth.uid()) then raise exception 'Character edit not permitted' using errcode='42501'; end if;
 perform bitd.validate_character_patch(p_patch);
 perform bitd.validate_character_playbook_patch(result.data->>'playbook',p_patch);
 merged := result.data || p_patch;
